import builtins
import logging
import os
import sys
from interops.libraries.desktop.configuration import Config
import interops.libraries.desktop.config_constants as cfg
from builtins import str
from interops.libraries.miscellaneous.remote_py_functions import execute_remote_py_function

# Get the current python installation path
python_install_path = sys.exec_prefix
sharedconfig_path = os.path.abspath(os.path.join(
    python_install_path, cfg.DEFAULT_SHAREDCONFIG_PATH))
# Load the sharedconfig.cfg file
Config.load(sharedconfig_path)
squish_bin_path = Config.get("system.squish_bin", cfg.DEFAULT_DEV_SQUISH_BIN_PATH)
squish_python_lib_path = Config.get("system.squish_python_lib", cfg.DEFAULT_DEV_SQUISH_LIB_PATH)
sys.path.extend([squish_bin_path, squish_python_lib_path])

from remotesystem import RemoteSystem


logger = logging.getLogger(__name__)


def isRunningLocal():
    #   Determine whether we're running on a client-server configuration or all on same machine.
    import squishtest3 as sq
    hostname = sq.currentApplicationContext().host
    if hostname.startswith("localhost") or hostname.startswith("127.0.0.0"):
        return True
    else:
        return False


def getRegistryValue(key, value_name, hive="HLM", mode="None"):
    #  Get the registry value held for the key and value_name under the given hive.
    #        See @readRegistryValue for more details.
    #
    #        e.g. Get Build value for RTD under HKEY_LOCAL_MACHINE:
    #             subkey = r'SOFTWARE\Elekta Oncology Systems Ltd\RTD'
    #             value_name = 'Build
    #             hive = "HLM"
    #  Depending on the mode we are passed read the registry on the local machine or remote machine
    #  If mode not passed in we try to work it out for ourselves, but better to make this explicit by
    #  setting the mode when we are called

    logger.debug("key: " + key)
    logger.debug("value_name: " + value_name)
    logger.debug("hive: " + hive)
    logger.debug("mode: " + mode)

    if mode == 'None':
        # Switch on client-server or local setup.
        if isRunningLocal():
            regval = readRegistryValue(key, value_name, hive)
        else:
            regval = execute_remote_py_function(readRegistryValue, [key, value_name, hive])
        return regval

    if mode == 'local':
        regval = readRegistryValue(key, value_name, hive)
        return regval

    if mode == 'remote':
        regval = execute_remote_py_function(readRegistryValue, [key, value_name, hive])
        return regval

    raise ValueError("mode argument not matched.")


def readRegistryValue(subkey, value_name, hive="HLM"):
    #     Retrieve value from Windows registry for the given subkey and value_name.
    #
    #        Default is to use the HKEY_LOCAL_MACHINE hive.
    #        To specify another hive use the hive kw with one of the following values:
    #        HLM - HKEY_LOCAL_MACHINE
    #        HCU - HKEY_CURRENT_USER
    #        HCC - HKEY_CURRENT_CONFIG
    #        HCR - HKEY_CLASSES_ROOT
    #        HU  - HKEY_USERS

    import winreg
    import platform
    # If this is a 64bit machine then add KEY_WOW64_64KEY value
    osIs64bit = platform.machine().endswith('64')
    if osIs64bit:
        access_mode = winreg.KEY_WOW64_64KEY + winreg.KEY_READ
    else:
        access_mode = winreg.KEY_READ
    # Switch on the hive kw
    if hive == "HLM":
        hive = winreg.HKEY_LOCAL_MACHINE
    elif hive == "HCU":
        hive = winreg.HKEY_CURRENT_USER
    elif hive == "HCC":
        winreg.HKEY_CURRENT_CONFIG
    elif hive == "HCR":
        hive = winreg.HKEY_CLASSES_ROOT
    elif hive == "HU":
        hive = winreg.HKEY_USERS

    try:
        reg_key = winreg.OpenKey(hive, subkey, 0, access_mode)
        value, regtype = winreg.QueryValueEx(reg_key, value_name)
        winreg.CloseKey(reg_key)
        return str(value)
    except WindowsError as e:
        # This function will be called remotely so no logger used (breaks dependencies when run remotely)
        print("No key found in registry: " + str(e))
    return None


def getRegistryValue_cmd_version(subkey, value_name, host, port, hive="HKLM"):
    # Alternative function to retrieve registry keys. Using windows built in reg tool
    # Subkey(string)
    # Value_name(string)
    # hive(string)- either HKLM,HKCU,HKCR,HKU,HKCC

    key_to_retrieve = "{}".format(os.path.join(hive, subkey))
    remoteOS = RemoteSystem(host, port)
    (exitcode, stdout, stderr) = remoteOS.execute(["REG", "QUERY", key_to_retrieve, "/v", value_name])
    if stderr:
        logger.exception("Could not read registry " + str(stderr))
        return 'Could not read registry'
    returned_value = stdout.split().pop()
    # Handles hex values returned by the reg query and converts to integer
    try:
        return str(builtins.int(returned_value, 0))
    except ValueError:
        return str(returned_value)


def setRegistryValue_cmd_version(subkey, value_name, reg_data_type, data_to_set, host, port, hive="HKLM"):
    # Alternative function to set registry keys. Using windows built in reg tool
    # Subkey(string)
    # reg_data_type(string)
    # data_to_set(string)
    # Value_name(string)
    # hive(string)- either HKLM,HKCU,HKCR,HKU,HKCC

    key_to_retrieve = "{}".format(os.path.join(hive, subkey))
    remoteOS = RemoteSystem(host, port)
    (exitcode, stdout, stderr) = remoteOS.execute(
        ["REG", "ADD", key_to_retrieve, "/v", value_name, "/t", reg_data_type, "/d", data_to_set, "/f"])
    if stderr:
        logger.exception("Could not update registry " + str(stderr))
        logger.info("Exit code for update registry " + str(exitcode))
        return 'Could not update registry'
    try:
        return str(builtins.int(stdout.strip(), 0))
    except ValueError:
        return str(stdout.strip())


def match_value_under_registry_subkey(subkey, value_name, expected_value, hive="HLM", mode=None):
    # subkey, value_name, expectedvalue, hive='HLM'
    #     Search entries under the subkey for the value_name key.
    #        If found and the value_name has the expectedvalue then True is returned.
    #        This function co-ordinates the search
    #        See @find_value_in_subkeys for more details.
    #
    #        e.g.
    #     subkey = r"SYSTEM\ControlSet001\Control\Class\{36FC9E60-C465-11CF-8056-444553540000}"
    #     value_name = "ProviderName"
    #     expectedvalue = "FTDI"

    if mode is None:
        # Switch on client-server or local setup.
        if isRunningLocal():
            regval = find_value_in_subkeys(subkey, value_name, expected_value, hive)
        else:
            regval = execute_remote_py_function(find_value_in_subkeys, [subkey, value_name, expected_value, hive])
        return regval

    if mode == 'local':
        regval = find_value_in_subkeys(subkey, value_name, expected_value, hive)
        return regval

    if mode == 'remote':
        regval = execute_remote_py_function(find_value_in_subkeys, [subkey, value_name, expected_value, hive])
        return regval

    raise ValueError("mode argument not matched.")


def find_value_in_subkeys(parent_key, value_name, expected_value, hive='HLM'):

    # subkey = r"SYSTEM\ControlSet001\Control\Class\{36FC9E60-C465-11CF-8056-444553540000}"

    #     For a given parent_key, this function will iterate over sub keys and check the value_name field
    #     to determine whether it matches the expected_value.

    import winreg
    import platform
    # If this is a 64bit machine then add KEY_WOW64_64KEY value
    osIs64bit = platform.machine().endswith('64')
    if osIs64bit:
        access_mode = winreg.KEY_WOW64_64KEY + winreg.KEY_READ
    else:
        access_mode = winreg.KEY_READ
    # Switch on the hive kw
    if hive == "HLM":
        hive = winreg.HKEY_LOCAL_MACHINE
    elif hive == "HCU":
        hive = winreg.HKEY_CURRENT_USER
    elif hive == "HCC":
        winreg.HKEY_CURRENT_CONFIG
    elif hive == "HCR":
        hive = winreg.HKEY_CLASSES_ROOT
    elif hive == "HU":
        hive = winreg.HKEY_USERS

    try:
        #
        reg_key = winreg.OpenKey(hive, parent_key, 0, access_mode)
        # Iterate over subkeys until no more available
        idx = 0
        found = False
        match = False
        while not found and not match:
            try:
                # get next subkey
                reg_subkey = winreg.EnumKey(reg_key, idx)
                idx += 1
                # get value for the subkey
                tmp_key = parent_key + "\\" + reg_subkey
                entry = winreg.OpenKey(hive, tmp_key, 0, access_mode)
                value, regtype = winreg.QueryValueEx(entry, value_name)
                winreg.CloseKey(entry)
                if value == expected_value:
                    match = True
                    return match
            except WindowsError:
                break
        winreg.CloseKey(reg_key)
    except WindowsError as e:
        # This function will be called remotely so no logger used (breaks dependencies when run remotely)
        print("No key found in registry: " + str(e))
    return match

